svg.script:
{
  "metadata": {"title": "UML Class Diagram", "projectName": "Food Delivery System", "description": "Object-oriented structure with classes, attributes, operations, and relationships", "version": "1.0", "mode": "light"},
  "config": {"layout": {"canvasWidth": 1920, "canvasHeight": 1080}, "styling": {"mode": "light", "canvasColor": "#FFFFFF", "fillColor": "#FFFFFF", "strokeColor": "#334155", "cornerRadius": 8, "strokeWidth": 1.5}},
  "data": {
    "classes": [
      {"id": "class1", "name": "ClassA", "x": 180, "y": 220, "width": 220, "height": 110, "attributes": ["+ attribute1", "+ attribute2"], "operations": ["+ operation1()", "+ operation2()"]},
      {"id": "class2", "name": "ClassB", "x": 760, "y": 180, "width": 220, "height": 110, "attributes": ["+ attribute1"], "operations": ["+ operation1()"]},
      {"id": "class3", "name": "ClassC", "x": 1340, "y": 240, "width": 220, "height": 110, "attributes": ["+ attribute1"], "operations": ["+ operation1()"]}
    ],
    "relationships": [
      {"from": "class1", "to": "class2", "type": "association", "multiplicity": "1"},
      {"from": "class2", "to": "class3", "type": "association", "multiplicity": "1"}
    ]
  }
}

(function() {
  const dataElement = document.currentScript.closest('svg').querySelector('#uml-class-diagram-data');
  if (!dataElement) return;
  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[UML Class Diagram Data] Loaded:', data.metadata.title);
  } catch (e) {
    console.error('[UML Class Diagram] Invalid JSON:', e.message);
  }
})();
